package studio.solocamera;

import android.content.Context;
import android.media.*;
import android.media.projection.MediaProjection;
import android.os.SystemClock;
import java.io.*;
import java.nio.*;
import java.util.function.BiConsumer;
import java.util.function.Consumer;

/** 48k mono PCM to the peer, and AAC sidecar for the optional phone recording. */
final class ScreenLiveAudio implements AutoCloseable {
    static final int RATE=48000,SAMPLES=960;
    private AudioRecord mic,app;private volatile boolean stopped;private Thread thread;private MediaCodec encoder;private MediaMuxer muxer;private int track=-1;private boolean muxStarted;private final File file;private long origin;
    private final BiConsumer<byte[],Long> output;private final Consumer<String> failure;
    ScreenLiveAudio(Context c,MediaProjection projection,boolean microphone,boolean playback,long origin,BiConsumer<byte[],Long> output,Consumer<String> failure)throws Exception{
        this.origin=origin;this.output=output;this.failure=failure;file=File.createTempFile("screen-live-audio-",".m4a",c.getCacheDir());
        try{if(c.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED)throw new SecurityException("Allow microphone/audio capture permission first");AudioFormat format=new AudioFormat.Builder().setEncoding(AudioFormat.ENCODING_PCM_16BIT).setSampleRate(RATE).setChannelMask(AudioFormat.CHANNEL_IN_MONO).build();int size=Math.max(RATE/5*2,AudioRecord.getMinBufferSize(RATE,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT));if(microphone)mic=new AudioRecord.Builder().setAudioSource(MediaRecorder.AudioSource.MIC).setAudioFormat(format).setBufferSizeInBytes(size).build();if(playback)app=new AudioRecord.Builder().setAudioPlaybackCaptureConfig(new AudioPlaybackCaptureConfiguration.Builder(projection).addMatchingUsage(AudioAttributes.USAGE_MEDIA).addMatchingUsage(AudioAttributes.USAGE_GAME).addMatchingUsage(AudioAttributes.USAGE_UNKNOWN).build()).setAudioFormat(format).setBufferSizeInBytes(size).build();
            encoder=MediaCodec.createEncoderByType("audio/mp4a-latm");MediaFormat aac=MediaFormat.createAudioFormat("audio/mp4a-latm",RATE,1);aac.setInteger(MediaFormat.KEY_AAC_PROFILE,MediaCodecInfo.CodecProfileLevel.AACObjectLC);aac.setInteger(MediaFormat.KEY_BIT_RATE,96000);encoder.configure(aac,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);encoder.start();muxer=new MediaMuxer(file.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);if(mic!=null)mic.startRecording();if(app!=null)app.startRecording();if((mic!=null&&mic.getRecordingState()!=AudioRecord.RECORDSTATE_RECORDING)||(app!=null&&app.getRecordingState()!=AudioRecord.RECORDSTATE_RECORDING))throw new IOException("Audio input did not start");thread=new Thread(this::run,"screen-live-audio");thread.start();
        }catch(Exception e){close();file.delete();throw e;}
    }
    private void run(){short[] voice=new short[SAMPLES],sound=new short[SAMPLES];long samples=0,first=SystemClock.elapsedRealtimeNanos()/1000;try{while(!stopped){java.util.Arrays.fill(voice,(short)0);java.util.Arrays.fill(sound,(short)0);int count=mic!=null?mic.read(voice,0,SAMPLES,AudioRecord.READ_BLOCKING):app.read(sound,0,SAMPLES,AudioRecord.READ_BLOCKING);if(count<0){if(!stopped)throw new IOException("Audio capture failed ("+count+")");break;}if(count==0)continue;if(mic!=null&&app!=null){int read=app.read(sound,0,count,AudioRecord.READ_NON_BLOCKING);if(read<0)throw new IOException("App audio capture failed ("+read+")");}byte[] pcm=new byte[count*2];ByteBuffer bytes=ByteBuffer.wrap(pcm).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<count;i++){int mixed=voice[i]+sound[i];bytes.putShort((short)Math.max(-32768,Math.min(32767,mixed)));}long stamp=first+samples*1_000_000/RATE;samples+=count;output.accept(pcm,stamp);encode(pcm,Math.max(0,stamp-origin));}flush();}catch(Exception e){if(!stopped)failure.accept("Live audio stopped: "+e.getMessage());}finally{release();}}
    private void encode(byte[] pcm,long time)throws Exception{int input=encoder.dequeueInputBuffer(10000);if(input>=0){ByteBuffer b=encoder.getInputBuffer(input);b.clear();b.put(pcm);encoder.queueInputBuffer(input,0,pcm.length,time,0);}else throw new IOException("Audio encoder input timed out");drain(false);}
    private void flush()throws Exception{if(encoder==null)return;int input=encoder.dequeueInputBuffer(10000);if(input>=0)encoder.queueInputBuffer(input,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);drain(true);}
    private void drain(boolean end)throws Exception{MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();for(int tries=0;tries<(end?100:8);tries++){int id=encoder.dequeueOutputBuffer(info,end?10000:0);if(id==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){track=muxer.addTrack(encoder.getOutputFormat());muxer.start();muxStarted=true;}else if(id>=0){ByteBuffer b=encoder.getOutputBuffer(id);if(muxStarted&&info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){b.position(info.offset);b.limit(info.offset+info.size);muxer.writeSampleData(track,b,info);}encoder.releaseOutputBuffer(id,false);if((info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0)return;}else if(id==MediaCodec.INFO_TRY_AGAIN_LATER&&!end)return;}}
    private void release(){for(AudioRecord r:new AudioRecord[]{mic,app})if(r!=null)try{r.release();}catch(Exception ignored){}mic=app=null;if(encoder!=null){try{encoder.stop();encoder.release();}catch(Exception ignored){}encoder=null;}if(muxer!=null){try{if(muxStarted)muxer.stop();}catch(Exception ignored){}try{muxer.release();}catch(Exception ignored){}muxer=null;}}
    File file(){return file;}
    @Override public void close(){stopped=true;for(AudioRecord r:new AudioRecord[]{mic,app})if(r!=null)try{r.stop();}catch(Exception ignored){}if(thread!=null){try{thread.join(3000);}catch(InterruptedException e){Thread.currentThread().interrupt();}}else release();}
    static void attach(Context c,android.net.Uri video,File audio)throws Exception{if(!audio.isFile()||audio.length()<100)return;File combined=File.createTempFile("screen-live-mux-",".mp4",c.getCacheDir());try{MediaMuxer mux=new MediaMuxer(combined.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);MediaExtractor v=new MediaExtractor(),a=new MediaExtractor();try{v.setDataSource(c,video,null);a.setDataSource(audio.getAbsolutePath());int vt=-1,at=-1;for(int i=0;i<v.getTrackCount();i++)if(v.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith("video/")){v.selectTrack(i);vt=mux.addTrack(v.getTrackFormat(i));break;}for(int i=0;i<a.getTrackCount();i++)if(a.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith("audio/")){a.selectTrack(i);at=mux.addTrack(a.getTrackFormat(i));break;}if(vt<0||at<0)throw new IOException("Recorded audio/video track missing");mux.start();copy(v,mux,vt);copy(a,mux,at);mux.stop();}finally{v.release();a.release();mux.release();}try(InputStream input=new FileInputStream(combined);OutputStream output=c.getContentResolver().openOutputStream(video,"wt")){if(output==null)throw new IOException("Cannot save mixed audio");byte[] bytes=new byte[65536];for(int count;(count=input.read(bytes))>=0;)output.write(bytes,0,count);}}finally{combined.delete();audio.delete();}}
    private static void copy(MediaExtractor e,MediaMuxer mux,int track){ByteBuffer buffer=ByteBuffer.allocateDirect(4*1024*1024);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(true){buffer.clear();int size=e.readSampleData(buffer,0);if(size<0)break;info.set(0,size,e.getSampleTime(),(e.getSampleFlags()&MediaExtractor.SAMPLE_FLAG_SYNC)!=0?MediaCodec.BUFFER_FLAG_KEY_FRAME:0);mux.writeSampleData(track,buffer,info);e.advance();}}
}
